#!/bin/bash
# Compatibility wrapper. Font IDs are generated by scripts/build_font_ids.py,
# which owns every id the firmware uses (header hashes, role aliases and the
# system-font-pack signature). Prefer calling that script directly; this file
# stays so existing habits and build notes keep working.
set -e
exec python3 "$(dirname "$0")/../../../scripts/build_font_ids.py" "$@"
